const VIEW = { full: "-92.05 -88.49 1260.9 1260.9", header: "-59.7 -61.93 1208.8 1208.8" };

/**
 * The mark, as the contract reads it. Only the orbit is paced by the turn, so only the orbit's
 * phase is carried across a change. The colours change with the state, which is what survives
 * reduced motion.
 */
const SPEC: MarkSpec = {
  id: "kawaii",
  beads: 7,
  paced: /^ck-[tnf]$/,
  liveClass: "cm-live",
  look: {
    rest: { "--ck-c0": "oklch(0.86 0.07 350)", "--ck-c1": "oklch(0.85 0.06 300)", "--ck-c2": "oklch(0.89 0.07 165)", "--ck-c3": "oklch(0.92 0.07 95)", "--ck-c4": "oklch(0.87 0.06 230)", "--ck-tw": "7s" },
    live: { "--ck-c0": "oklch(0.72 0.19 355)", "--ck-c1": "oklch(0.66 0.18 300)", "--ck-c2": "oklch(0.78 0.16 165)", "--ck-c3": "oklch(0.86 0.17 90)", "--ck-c4": "oklch(0.72 0.15 235)", "--ck-tw": "1.1s" },
  },
  turnVar: "--ck-turn",
  paperVar: "--ck-paper",
  view: VIEW,
};

export type KawaiiMarkProps = MarkProps;

export function KawaiiMark(props: KawaiiMarkProps) {
  const m = useMark(SPEC, props);
  // Memoised as an OBJECT, not a string: React 19 diffs dangerouslySetInnerHTML by identity, and a
  // fresh object every render would rebuild the markup and restart every animation.
  const body = useMemo(
    () => ({ __html: BODY[m.weight].replaceAll("__cmid__", `ck${m.uid}-`) }),
    [m.weight, m.uid],
  );
  return (
    <svg {...m.root}>
      <style>{STYLE}</style>
      <g className={m.live ? undefined : "ck-drift"} dangerouslySetInnerHTML={body} />
    </svg>
  );
}
